# Number references and figures by their first appearance in the manuscript.
ref_start=next(i for i,x in enumerate(main) if x['type']=='heading' and x['text']=='References')
ref_map={}
def citation_numbers(raw):
    out=[]
    for token in raw.split(','):
        nums=re.split(r'[–-]',token.strip())
        out.extend(range(int(nums[0]),int(nums[-1])+1))
    return out
for block in main[:ref_start]:
    for match in re.finditer(r'\[([0-9,– -]+)\]',block.get('text','')):
        for old in citation_numbers(match[1]):
            if old not in ref_map:ref_map[old]=len(ref_map)+1
assert set(ref_map)==set(range(1,30)),ref_map
for block in main[:ref_start]:
    if 'text' in block:
        block['text']=re.sub(r'\[([0-9,– -]+)\]',lambda m:'['+','.join(str(ref_map[n])for n in citation_numbers(m[1]))+']',block['text'])
ref_end=next(i for i in range(ref_start+1,len(main)) if main[i]['type']=='heading')
references=main[ref_start+1:ref_end]
for block in references:
    m=re.match(r'([0-9]+)\. ',block['text']);block['_order']=ref_map[int(m[1])]
    block['text']=re.sub(r'^[0-9]+\.',str(block['_order'])+'.',block['text'])
main[ref_start+1:ref_end]=sorted(references,key=lambda x:x['_order'])
fig_map={1:1,2:2,5:3,8:4,7:5,10:6,3:7,4:8,6:9,9:10}
