def md(blocks):
    out=[]
    for q in blocks:
        if q['type']=='title':out.append('# '+q['text'])
        elif q['type']=='heading':out.append('#'*(q['level']+1)+' '+q['text'])
        elif q['type']=='paragraph':out.append(q['text'])
        elif q['type']=='equation':out.append(q['text'])
        elif q['type']=='table':out.extend([q['title'],'| '+' | '.join(q['headers'])+' |','| '+' | '.join(['---']*len(q['headers']))+' |']+['| '+' | '.join(str(x).replace('|',' / ').replace('\n',' ')for x in row)+' |'for row in q['rows']])
        elif q['type']=='figure':out.extend([f"![{q['filename']}](publication_figures/{q['filename']}.png)",q['caption']])
    return '\n\n'.join(out)+'\n'
(R/'manuscript_content.json').write_text(json.dumps(main,indent=2,ensure_ascii=False)+'\n');(R/'supplement_content.json').write_text(json.dumps(supp,indent=2,ensure_ascii=False)+'\n')
